CREATE TABLE IF NOT EXISTS `tareas_eliminacion_operacion` (`operation_id` varchar(32) NOT NULL PRIMARY KEY, `reverses_operation_id` varchar(32) NULL, `actor_id` bigint UNSIGNED NOT NULL CHECK (`actor_id` >= 0), `empresa_id` bigint UNSIGNED NOT NULL CHECK (`empresa_id` >= 0), `root_task_id` bigint UNSIGNED NOT NULL CHECK (`root_task_id` >= 0), `root_correlativo` varchar(9) NOT NULL, `backend_type` varchar(16) NOT NULL, `backend_identity` varchar(160) NOT NULL, `backend_config_version` varchar(64) NOT NULL, `fingerprint` varchar(64) NOT NULL, `dependency_summary` longtext NOT NULL, `motivo` longtext NULL, `status` varchar(16) NOT NULL, `result_code` varchar(32) NOT NULL, `audit_status` varchar(16) NOT NULL, `audit_attempts` integer UNSIGNED NOT NULL CHECK (`audit_attempts` >= 0), `audit_last_attempt_at` datetime(6) NULL, `audit_event_id` bigint UNSIGNED NULL CHECK (`audit_event_id` >= 0), `audit_error_code` varchar(64) NOT NULL, `file_cleanup_status` varchar(16) NOT NULL, `created_at` datetime(6) NOT NULL, `updated_at` datetime(6) NOT NULL, `committed_at` datetime(6) NULL, CONSTRAINT `tareas_delop_motivo_required` CHECK ((NOT (`result_code` = 'LOGICALLY_DELETED') OR (`motivo` IS NOT NULL AND NOT (`motivo` = '' AND `motivo` IS NOT NULL)))), CONSTRAINT `tareas_delop_reverses_uniq` UNIQUE (`reverses_operation_id`), CONSTRAINT `tareas_delop_restore_link` CHECK (((`reverses_operation_id` IS NULL AND NOT (`result_code` = 'LOGICALLY_RESTORED')) OR (`result_code` = '' AND `reverses_operation_id` IS NOT NULL AND `status` = 'PENDING') OR (`result_code` = 'LOGICALLY_RESTORED' AND `reverses_operation_id` IS NOT NULL AND `status` = 'COMMITTED'))), CONSTRAINT `tareas_delop_restore_motive` CHECK (((NOT (`reverses_operation_id` IS NOT NULL) AND NOT (`result_code` = 'LOGICALLY_RESTORED')) OR (`motivo` IS NOT NULL AND NOT (`motivo` = '' AND `motivo` IS NOT NULL))))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `tareas_eliminacion_elemento` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `operacion_id` varchar(32) NOT NULL, `tipo` varchar(64) NOT NULL, `object_id` bigint UNSIGNED NOT NULL CHECK (`object_id` >= 0), CONSTRAINT `tareas_del_elemento_unico` UNIQUE (`operacion_id`, `tipo`, `object_id`)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `tareas_eliminacion_archivo` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `operacion_id` varchar(32) NOT NULL, `storage_key` varchar(64) NOT NULL, `file_name` varchar(500) NOT NULL, `reference_hash` varchar(64) NOT NULL, `status` varchar(16) NOT NULL, `attempts` integer UNSIGNED NOT NULL CHECK (`attempts` >= 0), `last_attempt_at` datetime(6) NULL, `error_code` varchar(64) NOT NULL, `created_at` datetime(6) NOT NULL, `updated_at` datetime(6) NOT NULL, CONSTRAINT `tareas_del_archivo_unico` UNIQUE (`operacion_id`, `storage_key`, `reference_hash`)) ENGINE=InnoDB;
